package com.aistock.prediction.explanation;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
public final class ExplanationRepository {
 private final com.aistock.prediction.maas.MaasOperationGate gate;private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final TransactionTemplate tx;
 public ExplanationRepository(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;gate=new com.aistock.prediction.maas.MaasOperationGate(jdbc);this.mapper=mapper;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 public record Claim(boolean execute,JsonNode receipt){}
 public Claim claim(UUID user,UUID prediction,UUID op,ExplanationFacts.Facts facts,Instant now){return tx.execute(s->{owned(user,prediction);var slot=gate.lock(now);var prior=operationRows(op);if(!prior.isEmpty()){var row=prior.get(0);if(!user.toString().equals(row.get("user_id"))||!prediction.toString().equals(row.get("prediction_id")))throw conflict();return new Claim(false,receipt(row));}var saved=jdbc.queryForList("select explanation_id from prediction_explanation where prediction_id=? and context_hash=?",String.class,prediction.toString(),facts.hash());if(saved.isEmpty()&&jdbc.queryForObject("select operation_id from prediction_explanation_slot where slot_id=1",String.class)!=null)throw HttpMaasClient.error("AI_BUSY");String result=saved.isEmpty()?null:saved.get(0);jdbc.update("insert into prediction_explanation_operation(operation_id,user_id,prediction_id,context_hash,context_json,state,explanation_id,created_at,lease_until,finished_at) values(?,?,?,?,?,?,?,?,?,?)",op.toString(),user.toString(),prediction.toString(),facts.hash(),json(facts.context()),result==null?"RUNNING":"SUCCEEDED",result,ts(now),ts(now.plusSeconds(50)),result==null?null:ts(now));if(result==null)gate.lockAndAcquire("PREDICTION_EXPLANATION",op,now);return new Claim(result==null,receipt(operationRows(op).get(0)));});}
 public JsonNode complete(UUID op,JsonNode paragraphs,String failure,Instant now){return tx.execute(s->{var slot=gate.lock(now);var rows=operationRows(op);if(rows.isEmpty())throw conflict();var row=rows.get(0);if(!"RUNNING".equals(row.get("state")))return receipt(row);if(!gate.owns(slot,"PREDICTION_EXPLANATION",op))throw conflict();String id=null;String code=failure;if(code==null){id=UUID.randomUUID().toString();jdbc.update("insert into prediction_explanation(explanation_id,prediction_id,context_hash,context_json,paragraphs_json,created_at) values(?,?,?,?,?,?)",id,row.get("prediction_id"),row.get("context_hash"),row.get("context_json"),json(paragraphs),ts(now));}else if(!code.matches("[A-Z0-9_]{1,64}"))code="AI_UNAVAILABLE";jdbc.update("update prediction_explanation_operation set state=?,explanation_id=?,error_code=?,finished_at=? where operation_id=?",id==null?"FAILED":"SUCCEEDED",id,code,ts(now),op.toString());gate.release("PREDICTION_EXPLANATION",op);return receipt(operationRows(op).get(0));});}
 public JsonNode read(UUID user,UUID prediction,String hash,Instant now){return tx.execute(s->{owned(user,prediction);var root=mapper.createObjectNode().put("currentContextHash",hash).put("stale",false);var results=jdbc.queryForList("select * from prediction_explanation where prediction_id=? order by (context_hash=?) desc,sequence_id desc limit 1",prediction.toString(),hash);root.putNull("latest");if(!results.isEmpty()){root.set("latest",result(results.get(0)));root.put("stale",!hash.equals(results.get(0).get("context_hash")));}var ops=jdbc.queryForList("select * from prediction_explanation_operation where user_id=? and prediction_id=? order by sequence_id desc limit 1",user.toString(),prediction.toString());root.putNull("latestAttempt");if(!ops.isEmpty()){var attempt=(ObjectNode)receipt(ops.get(0));attempt.put("expired","RUNNING".equals(ops.get(0).get("state"))&&!now.isBefore(instant(ops.get(0).get("lease_until"))));root.set("latestAttempt",attempt);}return root;});}
 private void owned(UUID user,UUID prediction){var rows=jdbc.queryForList("select state from forecast_request where user_id=? and prediction_id=?",user.toString(),prediction.toString());if(rows.isEmpty())throw new com.aistock.common.BusinessException("RESOURCE_NOT_FOUND","未找到记录",org.springframework.http.HttpStatus.NOT_FOUND);if(!"SUCCEEDED".equals(rows.get(0).get("state")))throw ExplanationFacts.invalid();}
 private List<Map<String,Object>> operationRows(UUID op){return jdbc.queryForList("select * from prediction_explanation_operation where operation_id=?",op.toString());}
 private JsonNode receipt(Map<String,Object> r){var n=mapper.createObjectNode();for(String key:List.of("operation_id","state","explanation_id","context_hash","error_code")){String name=switch(key){case "operation_id"->"operationId";case "explanation_id"->"explanationId";case "context_hash"->"contextHash";case "error_code"->"errorCode";default->key;};if(r.get(key)==null)n.putNull(name);else n.put(name,r.get(key).toString());}n.put("leaseUntil",instant(r.get("lease_until")).toString());return n;}
 private JsonNode result(Map<String,Object> r){var n=mapper.createObjectNode().put("explanationId",r.get("explanation_id").toString()).put("contextHash",r.get("context_hash").toString()).put("createdAt",instant(r.get("created_at")).toString());n.set("context",parse(r.get("context_json").toString()));n.set("paragraphs",parse(r.get("paragraphs_json").toString()));return n;}
 private Instant instant(Object value){return value instanceof Timestamp t?t.toInstant():((LocalDateTime)value).toInstant(ZoneOffset.UTC);}
 private Timestamp ts(Instant now){return Timestamp.from(now.truncatedTo(java.time.temporal.ChronoUnit.MILLIS));}private String json(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw ExplanationFacts.invalid();}}private JsonNode parse(String s){try{return mapper.readTree(s);}catch(Exception e){throw ExplanationFacts.invalid();}}private com.aistock.common.BusinessException conflict(){return new com.aistock.common.BusinessException("AI_REQUEST_CONFLICT","解释请求或状态已变更",org.springframework.http.HttpStatus.CONFLICT);}
}
